BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "aluno_turmas" (
	"id"	INTEGER,
	"aluno_id"	INTEGER NOT NULL,
	"turma_id"	INTEGER NOT NULL,
	"data_matricula"	DATETIME DEFAULT CURRENT_TIMESTAMP,
	"status"	TEXT DEFAULT 'cursando',
	UNIQUE("aluno_id","turma_id"),
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("aluno_id") REFERENCES "usuarios"("id"),
	FOREIGN KEY("turma_id") REFERENCES "turmas"("id")
);
CREATE TABLE IF NOT EXISTS "aulas" (
	"id"	INTEGER,
	"disciplina"	TEXT NOT NULL,
	"professor_id"	INTEGER NOT NULL,
	"sala_id"	INTEGER,
	"curso"	TEXT,
	"turma"	TEXT,
	"horario_inicio"	TIME NOT NULL,
	"horario_fim"	TIME NOT NULL,
	"data_aula"	DATE NOT NULL,
	"periodo"	INTEGER,
	"dia_semana"	INTEGER,
	"data_criacao"	DATETIME DEFAULT CURRENT_TIMESTAMP,
	"ativa"	BOOLEAN DEFAULT 1,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("professor_id") REFERENCES "professores"("id"),
	FOREIGN KEY("sala_id") REFERENCES "salas"("id")
);
CREATE TABLE IF NOT EXISTS "aulas_backup_cleanup" (
	"id"	INT,
	"disciplina_id"	INT,
	"professor_id"	INT,
	"sala_id"	INT,
	"curso"	TEXT,
	"turma"	TEXT,
	"horario_inicio"	NUM,
	"horario_fim"	NUM,
	"dia_semana"	TEXT,
	"ativa"	NUM
);
CREATE TABLE IF NOT EXISTS "blocos" (
	"id"	INTEGER,
	"letra"	TEXT NOT NULL UNIQUE,
	"nome"	TEXT,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "cursos" (
	"id"	INTEGER,
	"nome"	TEXT NOT NULL UNIQUE,
	"duracao"	INTEGER,
	"turno"	TEXT,
	"ativo"	BOOLEAN DEFAULT 1,
	"total_periodos"	INTEGER DEFAULT 8,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "disciplinas" (
	"id"	INTEGER,
	"nome"	TEXT NOT NULL,
	"curso_id"	INTEGER,
	"periodo"	INTEGER,
	"carga_horaria"	INTEGER,
	"ativa"	BOOLEAN DEFAULT 1,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "horarios" (
	"id"	INTEGER,
	"nome"	TEXT NOT NULL,
	"horario_inicio"	TIME NOT NULL,
	"horario_fim"	TIME NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "matriculas" (
	"id"	INTEGER,
	"aluno_id"	INTEGER,
	"disciplina_id"	INTEGER,
	"periodo"	INTEGER,
	"data_matricula"	DATETIME DEFAULT CURRENT_TIMESTAMP,
	"situacao"	TEXT DEFAULT 'cursando',
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" (
	"id"	INTEGER,
	"user_id"	INTEGER NOT NULL,
	"token"	TEXT NOT NULL UNIQUE,
	"expires_at"	DATETIME NOT NULL,
	"used"	BOOLEAN DEFAULT 0,
	"created_at"	DATETIME DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("user_id") REFERENCES "usuarios"("id")
);
CREATE TABLE IF NOT EXISTS "professores" (
	"id"	INTEGER,
	"nome"	TEXT NOT NULL,
	"email"	TEXT NOT NULL UNIQUE,
	"ativo"	BOOLEAN DEFAULT 1,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "professores_favoritos" (
	"id"	INTEGER,
	"aluno_id"	INTEGER,
	"professor_id"	INTEGER,
	"data_adicao"	DATETIME DEFAULT CURRENT_TIMESTAMP,
	UNIQUE("aluno_id","professor_id"),
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "salas" (
	"id"	INTEGER,
	"numero"	TEXT NOT NULL,
	"bloco"	TEXT NOT NULL,
	"andar"	INTEGER NOT NULL,
	"tipo"	TEXT NOT NULL,
	"capacidade"	INTEGER,
	"recursos"	TEXT,
	"ativa"	BOOLEAN DEFAULT 1,
	"campus"	TEXT DEFAULT 'Principal',
	"telefone"	TEXT,
	"email"	TEXT,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "salas_backup_cleanup" (
	"id"	INT,
	"numero"	TEXT,
	"bloco"	TEXT,
	"andar"	INT,
	"tipo"	TEXT,
	"capacidade"	INT,
	"recursos"	TEXT,
	"ativa"	NUM
);
CREATE TABLE IF NOT EXISTS "turmas" (
	"id"	INTEGER,
	"nome"	TEXT NOT NULL,
	"curso_id"	INTEGER,
	"periodo"	INTEGER,
	"ano"	INTEGER DEFAULT 2024,
	"ativa"	BOOLEAN DEFAULT 1,
	"quantidade_alunos"	INTEGER DEFAULT 0,
	"curso"	TEXT,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("curso_id") REFERENCES "cursos"("id")
);
CREATE TABLE IF NOT EXISTS "usuarios" (
	"id"	INTEGER,
	"nome"	TEXT NOT NULL,
	"email"	TEXT NOT NULL UNIQUE,
	"matricula"	TEXT UNIQUE,
	"tipo"	TEXT DEFAULT 'aluno',
	"curso"	TEXT,
	"periodo"	INTEGER,
	"senha_hash"	TEXT NOT NULL,
	"ativo"	BOOLEAN DEFAULT 1,
	"data_cadastro"	DATETIME DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id" AUTOINCREMENT)
);
