CREATE TRIGGER atualizar_quantidade_alunos
AFTER INSERT ON aluno_turmas
BEGIN
    UPDATE turmas 
    SET quantidade_alunos = (
        SELECT COUNT(*) 
        FROM aluno_turmas 
        WHERE turma_id = NEW.turma_id AND status = 'cursando'
    )
    WHERE id = NEW.turma_id;
END;
CREATE TRIGGER atualizar_quantidade_alunos_delete
AFTER DELETE ON aluno_turmas
BEGIN
    UPDATE turmas 
    SET quantidade_alunos = (
        SELECT COUNT(*) 
        FROM aluno_turmas 
        WHERE turma_id = OLD.turma_id AND status = 'cursando'
    )
    WHERE id = OLD.turma_id;
END;
COMMIT;
